minimal OpenAPI 3.0 specification, using FastMCP's OpenAPI integration.
"""

import httpx
from fastmcp import FastMCP

# --- Inputs: an OpenAPI 3.0 spec (dict) and a pre-configured async client ---

openapi_spec: dict = {
    "openapi": "3.0.0",
    "info": {"title": "Example API", "version": "1.0.0"},
    "paths": {
        "/items": {
            "get": {
                "operationId": "list_items",
                "summary": "List all items",
                "responses": {"200": {"description": "OK"}},
            },
            "post": {
                "operationId": "create_item",
                "summary": "Create a new item",
                "requestBody": {
                    "required": True,
                    "content": {
                        "application/json": {
                            "schema": {
                                "type": "object",
                                "properties": {"name": {"type": "string"}},
                                "required": ["name"],
                            }
                        }
                    },
                },
                "responses": {"201": {"description": "Created"}},
            },
        },
        "/items/{item_id}": {
            "get": {
                "operationId": "get_item",
                "summary": "Get a single item by ID",
                "parameters": [
                    {
                        "name": "item_id",
                        "in": "path",
                        "required": True,
                        "schema": {"type": "integer"},
                    }
                ],
                "responses": {"200": {"description": "OK"}},
            }
        },
    },
}

client = httpx.AsyncClient(base_url="https://api.example.com")

# --- Build the MCP server directly from the OpenAPI spec ---

mcp = FastMCP.from_openapi(
    openapi_spec=openapi_spec,
    client=client,
    name="Example API MCP Server",
)

if __name__ == "__main__":
    mcp.run()

